typedef struct {
    uint32_t key;
    uint32_t value;
} z_t2380_entry_t;

typedef struct z_t2380_t {
    uint32_t length;
    uint32_t capacity;
    uint32_t* indices;
    z_t2380_entry_t* entries;
} z_t2380_t;

